#include <string>
#include <vector>

class Solution {
public:
    long long validSubstringCount(std::string word1, std::string word2) {
        int target[26] = {0};
        int needed = 0;
        for (char c : word2) {
            if (target[c - 'a'] == 0) needed++;
            target[c - 'a']++;
        }

        int window[26] = {0};
        int satisfied = 0;
        int left = 0;
        long long ans = 0;
        int n = word1.size();

        for (int right = 0; right < n; ++right) {
            int r_idx = word1[right] - 'a';
            window[r_idx]++;
            if (target[r_idx] > 0 && window[r_idx] == target[r_idx]) {
                satisfied++;
            }

            while (satisfied == needed) {
                ans += n - right;
                int l_idx = word1[left] - 'a';
                if (target[l_idx] > 0 && window[l_idx] == target[l_idx]) {
                    satisfied--;
                }
                window[l_idx]--;
                left++;
            }
        }
        return ans;
    }
};

class Solution {
    public long validSubstringCount(String word1, String word2) {
        int[] target = new int[26];
        int needed = 0;
        for (int i = 0; i < word2.length(); i++) {
            int idx = word2.charAt(i) - 'a';
            if (target[idx] == 0) needed++;
            target[idx]++;
        }

        int[] window = new int[26];
        int satisfied = 0;
        int left = 0;
        long ans = 0;
        int n = word1.length();

        for (int right = 0; right < n; right++) {
            int rIdx = word1.charAt(right) - 'a';
            window[rIdx]++;
            if (target[rIdx] > 0 && window[rIdx] == target[rIdx]) {
                satisfied++;
            }

            while (satisfied == needed) {
                ans += n - right;
                int lIdx = word1.charAt(left) - 'a';
                if (target[lIdx] > 0 && window[lIdx] == target[lIdx]) {
                    satisfied--;
                }
                window[lIdx]--;
                left++;
            }
        }
        return ans;
    }
}

